window.KH_SURA(47, {"sura": "محمد", "n": 47, "ayat": {"1": "الَّذِينَ كَفَرُوا وَصَدُّوا عَنْ سَبِيلِ اللَّهِ أَضَلَّ أَعْمَالَهُمْ", "2": "وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَآمَنُوا بِمَا نُزِّلَ عَلَى مُحَمَّدٍ وَهُوَ الْحَقُّ مِنْ رَبِّهِمْ كَفَّرَ عَنْهُمْ سَيِّئَاتِهِمْ وَأَصْلَحَ بَالَهُمْ", "3": "ذَلِكَ بِأَنَّ الَّذِينَ كَفَرُوا اتَّبَعُوا الْبَاطِلَ وَأَنَّ الَّذِينَ آمَنُوا اتَّبَعُوا الْحَقَّ مِنْ رَبِّهِمْ كَذَلِكَ يَضْرِبُ اللَّهُ لِلنَّاسِ أَمْثَالَهُمْ", "4": "فَإِذَا لَقِيتُمُ الَّذِينَ كَفَرُوا فَضَرْبَ الرِّقَابِ حَتَّى إِذَا أَثْخَنْتُمُوهُمْ فَشُدُّوا الْوَثَاقَ فَإِمَّا مَنًّا بَعْدُ وَإِمَّا فِدَاءً حَتَّى تَضَعَ الْحَرْبُ أَوْزَارَهَا ذَلِكَ وَلَوْ يَشَاءُ اللَّهُ لَانْتَصَرَ مِنْهُمْ وَلَكِنْ لِيَبْلُوَ بَعْضَكُمْ بِبَعْضٍ وَالَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ فَلَنْ يُضِلَّ أَعْمَالَهُمْ", "5": "سَيَهْدِيهِمْ وَيُصْلِحُ بَالَهُمْ", "6": "وَيُدْخِلُهُمُ الْجَنَّةَ عَرَّفَهَا لَهُمْ", "7": "يَاأَيُّهَا الَّذِينَ آمَنُوا إِنْ تَنْصُرُوا اللَّهَ يَنْصُرْكُمْ وَيُثَبِّتْ أَقْدَامَكُمْ", "8": "وَالَّذِينَ كَفَرُوا فَتَعْسًا لَهُمْ وَأَضَلَّ أَعْمَالَهُمْ", "9": "ذَلِكَ بِأَنَّهُمْ كَرِهُوا مَا أَنْزَلَ اللَّهُ فَأَحْبَطَ أَعْمَالَهُمْ", "10": "أَفَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِنْ قَبْلِهِمْ دَمَّرَ اللَّهُ عَلَيْهِمْ وَلِلْكَافِرِينَ أَمْثَالُهَا", "11": "ذَلِكَ بِأَنَّ اللَّهَ مَوْلَى الَّذِينَ آمَنُوا وَأَنَّ الْكَافِرِينَ لَا مَوْلَى لَهُمْ", "12": "إِنَّ اللَّهَ يُدْخِلُ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ وَالَّذِينَ كَفَرُوا يَتَمَتَّعُونَ وَيَأْكُلُونَ كَمَا تَأْكُلُ الْأَنْعَامُ وَالنَّارُ مَثْوًى لَهُمْ", "13": "وَكَأَيِّنْ مِنْ قَرْيَةٍ هِيَ أَشَدُّ قُوَّةً مِنْ قَرْيَتِكَ الَّتِي أَخْرَجَتْكَ أَهْلَكْنَاهُمْ فَلَا نَاصِرَ لَهُمْ", "14": "أَفَمَنْ كَانَ عَلَى بَيِّنَةٍ مِنْ رَبِّهِ كَمَنْ زُيِّنَ لَهُ سُوءُ عَمَلِهِ وَاتَّبَعُوا أَهْوَاءَهُمْ", "15": "مَثَلُ الْجَنَّةِ الَّتِي وُعِدَ الْمُتَّقُونَ فِيهَا أَنْهَارٌ مِنْ مَاءٍ غَيْرِ آسِنٍ وَأَنْهَارٌ مِنْ لَبَنٍ لَمْ يَتَغَيَّرْ طَعْمُهُ وَأَنْهَارٌ مِنْ خَمْرٍ لَذَّةٍ لِلشَّارِبِينَ وَأَنْهَارٌ مِنْ عَسَلٍ مُصَفًّى وَلَهُمْ فِيهَا مِنْ كُلِّ الثَّمَرَاتِ وَمَغْفِرَةٌ مِنْ رَبِّهِمْ كَمَنْ هُوَ خَالِدٌ فِي النَّارِ وَسُقُوا مَاءً حَمِيمًا فَقَطَّعَ أَمْعَاءَهُمْ", "16": "وَمِنْهُمْ مَنْ يَسْتَمِعُ إِلَيْكَ حَتَّى إِذَا خَرَجُوا مِنْ عِنْدِكَ قَالُوا لِلَّذِينَ أُوتُوا الْعِلْمَ مَاذَا قَالَ آنِفًا أُولَئِكَ الَّذِينَ طَبَعَ اللَّهُ عَلَى قُلُوبِهِمْ وَاتَّبَعُوا أَهْوَاءَهُمْ", "17": "وَالَّذِينَ اهْتَدَوْا زَادَهُمْ هُدًى وَآتَاهُمْ تَقْوَاهُمْ", "18": "فَهَلْ يَنْظُرُونَ إِلَّا السَّاعَةَ أَنْ تَأْتِيَهُمْ بَغْتَةً فَقَدْ جَاءَ أَشْرَاطُهَا فَأَنَّى لَهُمْ إِذَا جَاءَتْهُمْ ذِكْرَاهُمْ", "19": "فَاعْلَمْ أَنَّهُ لَا إِلَهَ إِلَّا اللَّهُ وَاسْتَغْفِرْ لِذَنْبِكَ وَلِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَاللَّهُ يَعْلَمُ مُتَقَلَّبَكُمْ وَمَثْوَاكُمْ", "20": "وَيَقُولُ الَّذِينَ آمَنُوا لَوْلَا نُزِّلَتْ سُورَةٌ فَإِذَا أُنْزِلَتْ سُورَةٌ مُحْكَمَةٌ وَذُكِرَ فِيهَا الْقِتَالُ رَأَيْتَ الَّذِينَ فِي قُلُوبِهِمْ مَرَضٌ يَنْظُرُونَ إِلَيْكَ نَظَرَ الْمَغْشِيِّ عَلَيْهِ مِنَ الْمَوْتِ فَأَوْلَى لَهُمْ", "21": "طَاعَةٌ وَقَوْلٌ مَعْرُوفٌ فَإِذَا عَزَمَ الْأَمْرُ فَلَوْ صَدَقُوا اللَّهَ لَكَانَ خَيْرًا لَهُمْ", "22": "فَهَلْ عَسَيْتُمْ إِنْ تَوَلَّيْتُمْ أَنْ تُفْسِدُوا فِي الْأَرْضِ وَتُقَطِّعُوا أَرْحَامَكُمْ", "23": "أُولَئِكَ الَّذِينَ لَعَنَهُمُ اللَّهُ فَأَصَمَّهُمْ وَأَعْمَى أَبْصَارَهُمْ", "24": "أَفَلَا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَا", "25": "إِنَّ الَّذِينَ ارْتَدُّوا عَلَى أَدْبَارِهِمْ مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمُ الْهُدَى الشَّيْطَانُ سَوَّلَ لَهُمْ وَأَمْلَى لَهُمْ", "26": "ذَلِكَ بِأَنَّهُمْ قَالُوا لِلَّذِينَ كَرِهُوا مَا نَزَّلَ اللَّهُ سَنُطِيعُكُمْ فِي بَعْضِ الْأَمْرِ وَاللَّهُ يَعْلَمُ إِسْرَارَهُمْ", "27": "فَكَيْفَ إِذَا تَوَفَّتْهُمُ الْمَلَائِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَارَهُمْ", "28": "ذَلِكَ بِأَنَّهُمُ اتَّبَعُوا مَا أَسْخَطَ اللَّهَ وَكَرِهُوا رِضْوَانَهُ فَأَحْبَطَ أَعْمَالَهُمْ", "29": "أَمْ حَسِبَ الَّذِينَ فِي قُلُوبِهِمْ مَرَضٌ أَنْ لَنْ يُخْرِجَ اللَّهُ أَضْغَانَهُمْ", "30": "وَلَوْ نَشَاءُ لَأَرَيْنَاكَهُمْ فَلَعَرَفْتَهُمْ بِسِيمَاهُمْ وَلَتَعْرِفَنَّهُمْ فِي لَحْنِ الْقَوْلِ وَاللَّهُ يَعْلَمُ أَعْمَالَكُمْ", "31": "وَلَنَبْلُوَنَّكُمْ حَتَّى نَعْلَمَ الْمُجَاهِدِينَ مِنْكُمْ وَالصَّابِرِينَ وَنَبْلُوَ أَخْبَارَكُمْ", "32": "إِنَّ الَّذِينَ كَفَرُوا وَصَدُّوا عَنْ سَبِيلِ اللَّهِ وَشَاقُّوا الرَّسُولَ مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمُ الْهُدَى لَنْ يَضُرُّوا اللَّهَ شَيْئًا وَسَيُحْبِطُ أَعْمَالَهُمْ", "33": "يَاأَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَلَا تُبْطِلُوا أَعْمَالَكُمْ", "34": "إِنَّ الَّذِينَ كَفَرُوا وَصَدُّوا عَنْ سَبِيلِ اللَّهِ ثُمَّ مَاتُوا وَهُمْ كُفَّارٌ فَلَنْ يَغْفِرَ اللَّهُ لَهُمْ", "35": "فَلَا تَهِنُوا وَتَدْعُوا إِلَى السَّلْمِ وَأَنْتُمُ الْأَعْلَوْنَ وَاللَّهُ مَعَكُمْ وَلَنْ يَتِرَكُمْ أَعْمَالَكُمْ", "36": "إِنَّمَا الْحَيَاةُ الدُّنْيَا لَعِبٌ وَلَهْوٌ وَإِنْ تُؤْمِنُوا وَتَتَّقُوا يُؤْتِكُمْ أُجُورَكُمْ وَلَا يَسْأَلْكُمْ أَمْوَالَكُمْ", "37": "إِنْ يَسْأَلْكُمُوهَا فَيُحْفِكُمْ تَبْخَلُوا وَيُخْرِجْ أَضْغَانَكُمْ", "38": "هَاأَنْتُمْ هَؤُلَاءِ تُدْعَوْنَ لِتُنْفِقُوا فِي سَبِيلِ اللَّهِ فَمِنْكُمْ مَنْ يَبْخَلُ وَمَنْ يَبْخَلْ فَإِنَّمَا يَبْخَلُ عَنْ نَفْسِهِ وَاللَّهُ الْغَنِيُّ وَأَنْتُمُ الْفُقَرَاءُ وَإِنْ تَتَوَلَّوْا يَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ ثُمَّ لَا يَكُونُوا أَمْثَالَكُمْ"}, "units": [{"aya": 1, "title": "قوله: {وصدوا عن سبيل الله}", "mawsua": {"taliq": 6002, "masala": "قوله: {وصدوا عن سبيل الله}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن المراد بأعمالهم الإنفاق الذي أنفقوه في سفرتهم إلى بدر", "ashab": "مقاتل", "athar": [70713, 70716]}, {"n": 2, "t": "أن المراد بالأعمال: أعمالهم البرة في الجاهلية من صلة رحم ونحوه", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 6002, "mi": 1, "aya": 1, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 638 - 639", "qawl": "", "nass": "وقوله: {وصدوا} يحتمل أن يريد الفعل المجاوز، فيكون المعنى: وصدوا غيرهم. ويحتمل أن يكون الفعل غير متعد، فيكون المعنى: وصدوا أنفسهم", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 4, "title": "في قوله: ﴿حتى إذا أثخنتموهم فشدوا الوثاق فإما منا بعد وإما فداء﴾", "tabari": {"page": "21/183", "sarih": 1, "tarjih": "والصواب من القول عندنا في ذلك أن هذه الآية محكمة غير منسوخة، وذلك أن صفة الناسخ والمنسوخ ما قد بينا في غير موضع [من كتبنا] أنه ما لم يجز اجتماع حكميهما في حال واحدة، أو ما قامت الحجة بأن أحدهما ناسخ الآخر، وغير مستنكر أن يكون جعل الخيار في المن والفداء والقتل إلى رسول الله ﷺ، وإلى القائمين بعده بأمر الأمة، وإن لم يكن القتل مذكورا في هذه الآية؛ لأنه قد أذن بقتلهم في آية أخرى، وذلك قوله: ﴿فاقتلوا المشركين حيث وجدتموهم﴾ الآية. بل ذلك كذلك؛ لأن رسول الله ﷺ كذلك كان يفعل في من صار أسيرا في يده من أهل الحرب، فيقتل بعضا، ويفادى ببعض، ويمن على بعض، مثل يوم بدر؛ قتل عقبة بن أبي معيط وقد أتى به أسيرا، وقتل بني قريظة وقد نزلوا على حكم سعد، وصاروا في يده سلما، وهو على فدائهم والمن عليهم قادر، وفادى بجماعة أسارى المشركين الذين أسروا ببدر، ومن على ثمامة بن أثال الحنفى وهو أسير في يده، ولم يزل ذلك ثابتا من سيره في أهل الحرب، من لدن أذن الله له بحربهم إلى أن قبضه إليه ﷺ، دائما ذلك فيهم. وإنما ذكر جل ثناؤه في هذه الآية المن والفداء في الأسارى، فخص ذكرهما فيها؛ لأن الأمر بقتلهما والإذن منه بذلك قد كان تقدم في سائر آي تنزيله مكررا، فأعلم نبيه ﷺ بما ذكر في هذه الآية من المن والفداء ما له فيهم، مع القتل.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "هو منسوخ نسخه قوله: ﴿فاقتلوا المشركين حيث وجدتموهم﴾ [التوبة: ٥]. وقوله: ﴿فإما تثقفنهم في الحرب فشرد بهم من خلفهم﴾ [الأنفال: ٥٧]", "taqdim": 0, "n_athar": 7, "qailun": [["ابن جريج", "تابع التابعين"], ["السدي", "تابعي"], ["قتادة", "تابعي"], ["عبد الكريم الجزري", "تابع التابعين"], ["ابن عباس", "صحابي"]], "athar": [70730, 70732, 70733, 70742, 70743, 70754, 70755, 70756, 70757, 70759, 70774, 70775, 70782, 70784, 70786, 70787, 70789]}, {"n": 2, "t": "هي محكمة، وليست بمنسوخة. وقالوا: لا يجوز قتل الأسير، وإنما يجوز المن عليه والفداء", "taqdim": 0, "n_athar": 3, "qailun": [["الحسن", "تابعي"], ["عطاء", "تابعي"]], "athar": [70734, 70738, 70739, 70747, 70748, 70753, 70769, 70773]}]}, "mawaqif": [{"taliq": 6005, "mi": 1, "aya": 4, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "21/ 187 بتصرف", "qawl": "", "nass": "وذلك أن صفة الناسخ والمنسوخ أنه ما لم يجز اجتماع حكميهما في حال واحدة، أو ما قامت الحجة بأن أحدهما ناسخ الآخر، وغير مستنكر أن يكون جعل الخيار في المن والفداء والقتل إلى الرسول صلى الله عليه وسلم، وإلى القائمين بعده بأمر الأمة، وإن لم يكن القتل مذكورا في هذه الآية، لأنه قد أذن بقتلهم في آية أخرى، وذلك قوله: {فاقتلوا المشركين حيث وجدتموهم} الآية [التوبة: 5]، بل ذلك كذلك؛ لأن رسول الله صلى الله عليه وسلم كذلك كان يفعل فيمن صار أسيرا في يده من أهل الحرب، فيقتل بعضا، ويفادي ببعض، ويمن على بعض، مثل يوم بدر قتل عقبة بن أبي معيط وقد أتي به أسيرا، وقتل بني قريظة وقد نزلوا على حكم سعد، وصاروا في يده سلما، وهو على فدائهم والمن عليهم قادر، وفادى بجماعة أسارى المشركين الذين أسروا ببدر، ومن على ثمامة بن أثال الحنفي وهو أسير في يده، ولم يزل ذلك ثابتا من سيره في أهل الحرب من لدن أذن الله له بحربهم إلى أن قبضه إليه صلى الله عليه وسلم دائما ذلك فيهم، وإنما ذكر -جل ثناؤه- في هذه الآية المن والفداء في الأسا", "qawaid": ["غير ذلك", "السنة"], "tabi": ""}, {"taliq": 6005, "mi": 1, "aya": 4, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "7/ 640", "qawl": "", "nass": "وعلى قول أكثر العلماء الآيتان محكمتان. وقوله هنا: {فضرب الرقاب} بمثابة قوله هناك: {فاقتلوا المشركين حيث وجدتموهم}، وصرح هنا بذكر المن والفداء، ولم يصرح به هناك، وهو أمر متقرر، وهذا هو القول القوي", "qawaid": ["لم يذكر مستندًا"], "tabi": "ابن جرير"}, {"taliq": 6005, "mi": 1, "aya": 4, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "13/ 62", "qawl": "", "nass": "وهذا يقوي القول بعدم النسخ، كأنه شرع هذا الحكم في الحرب إلى ألا يبقى حرب", "qawaid": [], "tabi": ""}], "mushid": {"i": 1, "imgs": ["047_001_1.png"], "pages": [471], "n": 2, "rajih": [2], "daif": [], "match": true}, "mawsua": {"taliq": 6005, "masala": "هذه الآية أمحكمة هي أم منسوخة", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنها منسوخة بقوله تعالى: {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5]، وقوله: {واقتلوهم حيث ثقفتموهم} [البقرة: 191]", "ashab": "", "athar": []}, {"n": 2, "t": "أنها محكمة. وقال أصحاب هذا القول: إن قتل الأسير غير جائز، وإنما يجوز المن عليه والفداء", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن عطية", "r"], ["ابن جرير", "r"]]}, "t": {"2": [["ابن عطية", "r"], ["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن عطية": ["لم يذكر مستندًا"]}, "rulesD": {}}}, {"aya": 4, "title": "الغاية التي تضع الحرب عندها أوزارها", "mawsua": {"taliq": 6006, "masala": "الغاية التي تضع الحرب عندها أوزارها", "sigha": "في المسألة قولان", "nasib": "", "aqwal": [{"n": 1, "t": "حتى ينزل عيسى", "ashab": "", "athar": []}, {"n": 2, "t": "حتى لا يكون شرك ويسلم الجميع", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 6006, "mi": 1, "aya": 4, "alam": "ابن عطية", "fil": "زاد", "kind": "نقل", "ref": "7/ 641", "qawl": "", "nass": "حتى تغلبوهم وتقتلوهم", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 18, "title": "قوله: {فأنى لهم إذا جاءتهم ذكراهم}", "mawsua": {"taliq": 6019, "masala": "قوله: {فأنى لهم إذا جاءتهم ذكراهم}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يكون المعنى: فأنى لهم الخلاص أو النجاة إذ جاءتهم الذكرى بما كانوا يخبرون به في الدنيا فيكذبون به وجاءهم العذاب مع ذلك", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون المعنى: فأنى لهم ذكراهم وعملهم بحسبها إذا جاءتهم الساعة. وهذا تأويل قتادة، نظيره: {وأنى لهم التناوش من مكان بعيد} [سبأ: 52]", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 6019, "mi": 1, "aya": 18, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 649", "qawl": "", "nass": "وقوله تعالى: {فأنى لهم} الآية، يحتمل أن يكون المعنى: فأنى لهم الخلاص أو النجاة إذ جاءتهم الذكرى بما كانوا يخبرون به في الدنيا فيكذبون به وجاءهم العذاب مع ذلك. ويحتمل أن يكون المعنى: فأنى لهم ذكراهم وعملهم بحسبها إذا جاءتهم الساعة. وهذا تأويل قتادة، نظيره: {وأنى لهم التناوش من مكان بعيد} [سبأ: 52]", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 19, "title": "قوله: {متقلبكم ومثواكم}", "mawsua": {"taliq": 6020, "masala": "قوله: {متقلبكم ومثواكم}", "sigha": "في المسألة قولان", "nasib": "", "aqwal": [{"n": 1, "t": "أن معناه: يعلم تصرفكم في نهاركم، ومستقركم في ليلكم", "ashab": "", "athar": []}, {"n": 2, "t": "أن معناه: متقلبكم في الدنيا، ومثواكم في قبوركم", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 6020, "mi": 1, "aya": 19, "alam": "ابن كثير", "fil": "رجح", "kind": "ترجيح", "ref": "13/ 74", "qawl": "", "nass": "والأول أولى وأظهر", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [["ابن كثير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن كثير": ["لم يذكر مستندًا"]}, "rulesD": {}}}, {"aya": 21, "title": "قوله: {صدقوا}", "mawsua": {"taliq": 6025, "masala": "قوله: {صدقوا}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يكون من الصدق الذي هو ضد الكذب", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون من قولك: عود صدق", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 6025, "mi": 1, "aya": 21, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 652", "qawl": "", "nass": "وقوله: {صدقوا الله} يحتمل أن يكون من الصدق الذي هو ضد الكذب. ويحتمل أن يكون من قولك: عود صدق", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 25, "title": "تأويل: ﴿إن الذين ارتدوا على أدبارهم من بعد ما تبين لهم الهدى﴾", "tabari": {"page": "21/217", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿إن الذين ارتدوا على أدبارهم من بعد ما تبين لهم الهدى﴾. يقول الله ﷿: إن الذين رجعوا القهقرى على أعقابهم كفارا بالله من بعد ما تبين لهم الحق وقصد السبيل، فعرفوا واضح الحجة، ثم آثروا الضلال على الهدى، عنادا لأمر الله تعالى ذكره من بعد العلم.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "عنى بذلك أهل النفاق", "taqdim": 0, "n_athar": 2, "qailun": [["ابن عباس", "صحابي"]], "athar": [70943]}]}, "mawaqif": [], "mushid": {"i": 3, "imgs": ["047_003_1.png"], "pages": [471], "n": 2, "rajih": [1], "daif": [], "match": true}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 25, "title": "فاعل {أملى}", "mawsua": {"taliq": 6030, "masala": "فاعل {أملى}", "sigha": "في المسألة قولان", "nasib": "", "aqwal": [{"n": 1, "t": "أنه الشيطان", "ashab": "", "athar": []}, {"n": 2, "t": "أنه الله", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 6030, "mi": 1, "aya": 25, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 654", "qawl": "", "nass": "وذلك أن الإملاء: هو الإبقاء ملاوة من الدهر، يقال: ملاوة وملاوة وملاوة بضم الميم وفتحها وكسرها، وهي القطعة من الزمن، ومنه: الملوان الليل والنهار، فإذا أملى الشيطان إملاء ما فلا صحة له إلا بطمعهم الكاذب", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 32, "title": "قوله: {وصدوا}", "mawsua": {"taliq": 6034, "masala": "قوله: {وصدوا}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يكون المعنى: وصدوا غيرهم", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون غير متعد، بمعنى: وصدوهم في أنفسهم", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 6034, "mi": 1, "aya": 32, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 658 - 659", "qawl": "", "nass": "وقوله تعالى: {وصدوا} يحتمل أن يكون المعنى: وصدوا غيرهم. ويحتمل أن يكون غير متعد، بمعنى: وصدوهم في أنفسهم", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 35, "title": "تأويل: ﴿وتدعوا إلى السلم وأنتم الأعلون﴾", "tabari": {"page": "21/227", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "وقال: معنى قوله: ﴿وأنتم الأعلون﴾: أنتم أولى بالله منهم", "taqdim": 0, "n_athar": 3, "qailun": [["قتادة", "تابعي"]], "athar": [71000, 71004, 71007, 71015]}, {"n": 2, "t": "معنى قوله: ﴿وأنتم الأعلون﴾: أنتم الغالبون الأعز منهم", "taqdim": 0, "n_athar": 2, "qailun": [["مجاهد", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [70999, 71002, 71006, 71010, 71011, 71013, 71017]}]}, "mawaqif": [{"taliq": 6041, "mi": 1, "aya": 35, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "21/ 227", "qawl": "", "nass": "وقوله: {وأنتم الأعلون} وأنتم القاهرون لهم، والعالون عليهم", "qawaid": ["أقوال السلف"], "tabi": ""}], "mushid": {"i": 4, "imgs": ["047_004_1.png"], "pages": [472], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 6041, "masala": "قوله: {وأنتم الأعلون}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "وأنتم الغالبون لهم العالون عليهم", "ashab": "", "athar": []}, {"n": 2, "t": "وأنتم أولى بالله منهم", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 37, "title": "قوله: {ويخرج} يحتمل", "mawsua": {"taliq": 6044, "masala": "قوله: {ويخرج} يحتمل", "sigha": "ذكر ثلاثة احتمالات", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يكون الله تبارك وتعالى", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون البخل الذي يتضمنه اللفظ", "ashab": "", "athar": []}, {"n": 3, "t": "أن يكون السؤال الذي يتضمنه اللفظ أيضا", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 6044, "mi": 0, "aya": 37, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 662", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 38, "title": "تأويل: ﴿هاأنتم هؤلاء تدعون لتنفقوا في سبيل الله فمنكم من يبخل ومن يبخل فإنما يبخل عن نفسه والله ال﴾", "tabari": {"page": "21/232", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره للمؤمنين: هأنتم أيها الناس، ﴿هؤلاء تدعون لتنفقوا في سبيل الله﴾. يقول: تدعون إلى النفقة في جهاد أعداء الله ونصرة دينه، فمنكم من يبخل: بالنفقة فيه.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "جعل التنبية في موضعين للتوكيد", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 38, "title": "تأويل: ﴿وإن تتولوا يستبدل قوما غيركم﴾", "tabari": {"page": "21/234", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "وذكر أنه عنى بقوله: ﴿يستبدل قوما غيركم﴾. العجم من عجم فارس.", "taqdim": 1, "n_athar": 6, "qailun": [["قتادة", "تابعي"], ["ابن زيد", "تابع التابعين"], ["أبي هريرة", "صحابي"]], "athar": [71025, 71026, 71027, 71035, 71038]}, {"n": 2, "t": "هم أهل اليمن", "taqdim": 0, "n_athar": 1, "qailun": [], "athar": []}]}, "mawaqif": [], "mushid": {"i": 5, "imgs": ["047_005_1.png"], "pages": [472], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}], "extra": [{"i": 2, "aya": 4, "imgs": ["047_002_1.png"], "pages": [471], "ihala": 0}], "others": {"0": [{"id": 6000, "kinds": "غيره", "text": "قال ابنُ عطية (7/ 638): «هذه السورة مدنية بإجماع، غير أنّ بعض الناس قال في قوله تعالى: {وكَأَيِّنْ مِن قَرْيَةٍ هِيَ أشَدُّ قُوَّةً مِن قَرْيَتِكَ الَّتِي أخْرَجَتْكَ} [محمد: 13]: إنها نزلت بمكة في وقت دخول النبي فيها عام الفتح أو سنة الحُديبية. وما كان مثل هذا فهو معدود في المدني؛ لأن المراعى في ذلك إنما هو ما كان قبل الهجرة أو بعدها».", "mawaqif": [{"taliq": 6000, "mi": 0, "aya": 0, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 638", "qawl": "", "nass": "هذه السورة مدنية بإجماع، غير أن بعض الناس قال في قوله تعالى: {وكأين من قرية هي أشد قوة من قريتك التي أخرجتك} [محمد: 13]: إنها نزلت بمكة في وقت دخول النبي فيها عام الفتح أو سنة الحديبية. وما كان مثل هذا فهو معدود في المدني؛ لأن المراعى في ذلك إنما هو ما كان قبل الهجرة أو بعدها", "qawaid": [], "tabi": ""}]}], "1": [{"id": 6001, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (21/ 180 - 181) غير قول ابن عباس.", "mawaqif": []}], "2": [{"id": 6003, "kinds": "تعليق،نقل،حصر", "text": "لم يذكر ابنُ جرير (21/ 180 - 181) غيرَ قول ابن عباس.\nوذكر ابنُ عطية (7/ 638) القولَ بنزول الآية في الأنصار، ثم علّق بقوله: «ثم هي بعد تعمّ كل مَن دخل تحت ألفاظها».", "mawaqif": [{"taliq": 6003, "mi": 0, "aya": 2, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 638", "qawl": "بنزول الآية", "nass": "ثم هي بعد تعم كل من دخل تحت ألفاظها", "qawaid": [], "tabi": ""}]}, {"id": 6004, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 639) ما جاء في تفسير السلف البال بالحال والشأن والأمر، ثم علّق قائلًا: «وتحرير التفسير في اللفظة أنها بمعنى الفكر والموضع الذي فيه نظر الإنسان، وهو القلب، فإذا صلح ذلك صلحت حاله، فكأن اللفظة مشيرة إلى صلاح عقيدتهم، وغيرُ ذلك من الحال تابع، فقولك: خطر في بالي كذا، وقولك: أصلح الله بالك: المراد بهما واحد. ذكره المبرد».\nوعلّق ابنُ كثير (13/ 58) على هذه الأقوال الثلاثة بقوله: «والكل متقارب».", "mawaqif": [{"taliq": 6004, "mi": 0, "aya": 2, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 639", "qawl": "", "nass": "وتحرير التفسير في اللفظة أنها بمعنى الفكر والموضع الذي فيه نظر الإنسان، وهو القلب، فإذا صلح ذلك صلحت حاله، فكأن اللفظة مشيرة إلى صلاح عقيدتهم، وغير ذلك من الحال تابع، فقولك: خطر في بالي كذا، وقولك: أصلح الله بالك: المراد بهما واحد. ذكره المبرد", "qawaid": [], "tabi": ""}, {"taliq": 6004, "mi": 0, "aya": 2, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "13/ 58", "qawl": "", "nass": "والكل متقارب", "qawaid": [], "tabi": ""}]}], "4": [{"id": 6007, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (21/ 189) غير قول قتادة.", "mawaqif": []}, {"id": 6008, "kinds": "خلاف،ترجيح،توجيه،بيان،نقل", "text": "وجّه ابنُ جرير (21/ 190) المعنى على قراءات الآية، فقال: «وقوله: {والذين قاتلوا في سبيل الله} اختلفت القرّاء في قراءة ذلك، فقرأته عامة قراء الحجاز والكوفة: «والَّذِينَ قاتَلُواْ»، بمعنى: حاربوا المشركين، وجاهدوهم، بالألف. وكان الحسن البصري فيما ذُكر عنه يقرأه: (قُتِّلُوا) بضم القاف وتشديد التاء، بمعنى: أنه قتلهم المشركون بعضهم بعد بعض، غير أنّه لم يسمّ الفاعلون. وذكر عن الجحدري عاصم أنه كان يقرأه (والَّذِينَ قَتَلُوا) بفتح القاف وتخفيف التاء، بمعنى: والذين قتلوا المشركين بالله. وكان أبو عمرو يقرأه {قُتلوا} بضم القاف وتخفيف التاء بمعنى: والذين قتلهم المشركون، ثم أسقط الفاعلين، فجعلهم لم يُسمَّ فاعل ذلك بهم». ثم رجّح -مستندًا لإجماع الحجة من القراء- قراءة «قاتَلُواْ»، فقال: «وأولى القراءات بالصواب قراءة من قرأه: «والَّذِينَ قاتَلُواْ»؛ لاتفاق الحجة من القراء، وإن كان لجميعها وجوه مفهومة».\nوبنحوه قال ابنُ عطية (7/ 642) حيث قال: «والقراءة الأولى أعمُّها وأوضحها معنى».\nثم وجّه ابنُ جرير معنى الآية عليها، فقال: «وإذ كان ذلك أولى القراءات عندنا بالصواب فتأويل الكلام: والذين قاتلوا منكم -أيها المؤمنون- أعداء الله مِن الكفار في دين الله، وفي نصرة ما بعث به رسوله محمدًا صلى الله عليه وسلم من الهُدى، فجاهدوهم في ذلك، {فلن يضل أعمالهم} فلن يجعل الله أعمالهم التي عملوها في الدنيا ضلالًا عليهم كما أضلّ أعمال الكافرين».", "mawaqif": [{"taliq": 6008, "mi": 0, "aya": 4, "alam": "ابن جرير", "fil": "وجه", "kind": "توجيه", "ref": "21/ 190", "qawl": "", "nass": "وقوله: {والذين قاتلوا في سبيل الله} اختلفت القراء في قراءة ذلك، فقرأته عامة قراء الحجاز والكوفة: «والذين قاتلوا", "qawaid": ["القراءة ورسم المصحف"], "tabi": ""}, {"taliq": 6008, "mi": 0, "aya": 4, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 642", "qawl": "", "nass": "والقراءة الأولى أعمها وأوضحها معنى", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 6008, "mi": 0, "aya": 4, "alam": "ابن جرير", "fil": "وجه", "kind": "توجيه", "ref": "", "qawl": "", "nass": "وإذ كان ذلك أولى القراءات عندنا بالصواب فتأويل الكلام: والذين قاتلوا منكم -أيها المؤمنون- أعداء الله من الكفار في دين الله، وفي نصرة ما بعث به رسوله محمدا صلى الله عليه وسلم من الهدى، فجاهدوهم في ذلك، {فلن يضل أعمالهم} فلن يجعل الله أعمالهم التي عملوها في الدنيا ضلالا عليهم كما أضل أعمال الكافرين", "qawaid": [], "tabi": ""}]}], "6": [{"id": 6009, "kinds": "تعليق،نقل،حصر", "text": "لم يذكر ابنُ جرير (21/ 191 - 192) غير قول ابن زيد، وقتادة، ومجاهد من طريق ابن أبي نجيح.\nوعلّق على ما جاء في هذا القول ابنُ عطية (7/ 642)، فقال: «وفي نحو هذا المعنى هو قول النبي عليه السلام: «لأحدكم بمنزله في الجنّة أعرف منه بمنزله في الدنيا»».\nثم ذكر ابنُ عطية قولَ مَن قال معناه: طيّبها. وعلّق عليه قائلًا: «مأخوذ من العرْف، ومنه: طعام معرف، أي: مُطيّب. وعرفت القدر: طيّبتها بالملح والتابل».\nوذكر قولًا آخر أن المعنى: سمّاها لهم ورسمها، كل منزل باسم صاحبه. وعلّق عليه قائلًا: «فهذا نحو من التعريف».\nوذكر قولًا آخر أنّ ذلك معناه: شرّفها لهم، ورفعها، وعلّاها. وعلّق عليه بقوله: «وهذا مِن الأعراف، التي هي الجبال وما أشبهها، ومنه: أعراف الخيل».", "mawaqif": [{"taliq": 6009, "mi": 0, "aya": 6, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "", "nass": "مأخوذ من العرف، ومنه: طعام معرف، أي: مطيب. وعرفت القدر: طيبتها بالملح والتابل", "qawaid": [], "tabi": ""}]}], "8": [{"id": 6010, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (21/ 193 - 194) غير قول ابن زيد.", "mawaqif": []}], "10": [{"id": 6011, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 644) في عود الضمير في قوله: {أمثالها} احتمالين، فقال: «والضمير في قوله: {أمْثالُها} يصح أن يعود على العاقبة المذكورة، ويصح أن يعود على الفعلة التي يتضمنها قوله: {دَمَّرَ اللَّهُ عَلَيْهِمْ}».", "mawaqif": [{"taliq": 6011, "mi": 0, "aya": 10, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 644", "qawl": "", "nass": "والضمير في قوله: {أمثالها} يصح أن يعود على العاقبة المذكورة، ويصح أن يعود على الفعلة التي يتضمنها قوله: {دمر الله عليهم}", "qawaid": [], "tabi": ""}]}], "13": [{"id": 6012, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 645) في نزول هذه الآية عدة أقوال، فقال: «ويقال: إنّ هذه الآية نزلت إثر خروج رسول الله صلى الله عليه وسلم من مكة في طريق المدينة. وقيل: نزلت بالمدينة. وقيل: نزلت بمكة عام دخلها رسول الله صلى الله عليه وسلم بعد الحديبية. وقيل نزلت: عام الفتح وهو مقبل إليها». ثم علّق عليها جميعًا بقوله: «وهذا كله حكمه حكم المدني».", "mawaqif": [{"taliq": 6012, "mi": 0, "aya": 13, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 645", "qawl": "", "nass": "ويقال: إن هذه الآية نزلت إثر خروج رسول الله صلى الله عليه وسلم من مكة في طريق المدينة. وقيل: نزلت بالمدينة. وقيل: نزلت بمكة عام دخلها رسول الله صلى الله عليه وسلم بعد الحديبية. وقيل نزلت: عام الفتح وهو مقبل إليها", "qawaid": [], "tabi": ""}]}], "14": [{"id": 6013, "kinds": "بيان،تعليق،نقل", "text": "قال ابنُ جرير (21/ 199): «وقيل: إنّ الذي عني بقوله: {أفمن كان على بينة من ربه}: نبيّنا عليه الصلاة والسلام، وإنّ الذي عني بقوله: {كمن زين له سوء عمله}: هم المشركون».\nوذكر ذلك ابنُ عطية (5/ 113)، ثم علّق قائلًا: «وبقي اللفظ عامًّا لأهل هاتين الصفتين غابر الدهر».", "mawaqif": [{"taliq": 6013, "mi": 0, "aya": 14, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "21/ 199", "qawl": "", "nass": "وقيل: إن الذي عني بقوله: {أفمن كان على بينة من ربه}: نبينا عليه الصلاة والسلام، وإن الذي عني بقوله: {كمن زين له سوء عمله}: هم المشركون", "qawaid": [], "tabi": ""}]}, {"id": 6014, "kinds": "بيان،نقل", "text": "بيّن ابنُ عطية (7/ 645) أن قوله: {على بينة} معناه: «على قضية واضحة، وعقيدة نيّرة بيّنة». ثم ذكر احتمالًا آخر، فقال: «ويحتمل أن يكون المعنى: على أمر بيّن، ودين بيّن، وألحق الهاء للمبالغة كعلّامة ونسّابة».", "mawaqif": [{"taliq": 6014, "mi": 0, "aya": 14, "alam": "ابن عطية", "fil": "بين", "kind": "بيان", "ref": "7/ 645", "qawl": "", "nass": "على قضية واضحة، وعقيدة نيرة بينة", "qawaid": [], "tabi": ""}]}], "16": [{"id": 6015, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 647) أن المفسرين يقولون: {آنفا} معناه: الساعة الماضية القريبة منّا، وعلَّق عليه، بقوله: «وهذا تفسير بالمعنى».", "mawaqif": [{"taliq": 6015, "mi": 0, "aya": 16, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 647", "qawl": "", "nass": "وهذا تفسير بالمعنى", "qawaid": [], "tabi": ""}]}], "17": [{"id": 6016, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (21/ 205) غير قول ابن عباس.", "mawaqif": []}, {"id": 6017, "kinds": "ترجيح،تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 648) عدة احتمالات في الفاعل في قوله: {زادهم هدى}: الأول: أن يكون الفاعل الله تعالى. وعلّق عليه بقوله: «والزيادة في هذا المعنى تكون إما بزيادة التفهيم والأدلة، وإما بورود الشرائع والنواهي والأخبار فيزيد الاهتداء لتزيد علم ذلك كله والإيمان به وذلك بفضل الله تعالى». الثاني: أن يكون الفاعل قول المنافقين واضطرابهم في الآية التي قبلها. وعلّق عليه قائلًا: «لأن ذلك مما يتعجّب المؤمن منه ويحمد الله على إيمانه، ويتزيّد بصيرة في دينه، فكأنه قال: المهتدون والمؤمنون زادهم فعل هؤلاء المنافقين هدى، أي: كانت الزيادة بسببه، فأسند الفعل إليه». الثالث: أن يكون الفاعل النبي محمد صلى الله عليه وسلم، وذلك على قول مَن جعل الآية في قوم من النصارى. ثم علّق عليه قائلًا: «وقوله على هذا القول: {اهتدوا} يريد في إيمانهم بعيسى عليه السلام ثم زادهم محمد هدًى حين آمنوا به». ثم رجّح القول الأول بقوله: «وأقواها أن الفاعل الله تعالى». ولم يذكر مستندًا.", "mawaqif": [{"taliq": 6017, "mi": 0, "aya": 17, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 648", "qawl": "", "nass": "والزيادة في هذا المعنى تكون إما بزيادة التفهيم والأدلة، وإما بورود الشرائع والنواهي والأخبار فيزيد الاهتداء لتزيد علم ذلك كله والإيمان به وذلك بفضل الله تعالى", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}], "18": [{"id": 6018, "kinds": "توجيه", "text": "وجّه ابنُ جرير 21/ 206 هذه القراءة، فقال: «وتأويل الكلام على قراءة مَن قرأ ذلك بكسر ألف (إن) وجزم (تَأْتِهِمْ): فهل ينظرون إلا الساعة؟ فيجعل الخبر عن انتظار هؤلاء الكفار الساعة متناهيًا عند قوله: {إلا الساعة}، ثم يبتدأ الكلام فيقال: إن تأتهم الساعة بغتة فقد جاء أشراطها، فتكون الفاء من قوله: {فقد جاء} جواب الجزاء».", "mawaqif": [{"taliq": 6018, "mi": 0, "aya": 18, "alam": "ابن جرير", "fil": "وجه", "kind": "توجيه", "ref": "", "qawl": "", "nass": "وتأويل الكلام على قراءة من قرأ ذلك بكسر ألف (إن) وجزم (تأتهم): فهل ينظرون إلا الساعة؟ فيجعل الخبر عن انتظار هؤلاء الكفار الساعة متناهيا عند قوله: {إلا الساعة}، ثم يبتدأ الكلام فيقال: إن تأتهم الساعة بغتة فقد جاء أشراطها، فتكون الفاء من قوله: {فقد جاء} جواب الجزاء", "qawaid": [], "tabi": ""}]}], "20": [{"id": 6021, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (21/ 210) غير قول ابن زيد.", "mawaqif": []}, {"id": 6022, "kinds": "تعليق،نقل", "text": "قال ابنُ جرير (21/ 210): «وقوله: {وذكر فيها القتال} يقول: وذُكر فيها الأمر بقتال المشركين». ثم ذكر قول قتادة، ولم يعلق عليه.\nوعلّق ابنُ عطية (7/ 651) على قول قتادة، فقال: «وهذا أمر استقرأه قتادة مِن القرآن، وليس من تفسير هذه الآية في شيء».", "mawaqif": [{"taliq": 6022, "mi": 0, "aya": 20, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "21/ 210", "qawl": "", "nass": "وقوله: {وذكر فيها القتال} يقول: وذكر فيها الأمر بقتال المشركين", "qawaid": [], "tabi": ""}, {"taliq": 6022, "mi": 0, "aya": 20, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 651", "qawl": "قتادة", "nass": "وهذا أمر استقرأه قتادة من القرآن، وليس من تفسير هذه الآية في شيء", "qawaid": [], "tabi": ""}]}], "21": [{"id": 6023, "kinds": "بيان،تعليق", "text": "علّق ابنُ جرير (21/ 212) على قول ابن عباس، فقال: «فعلى هذا القول تمام الوعيد فأولى، ثم يستأنف بعد، فيقال: {لهم طاعة وقول معروف} فتكون الطاعة مرفوعة بقوله: {لهم}». وبيّن أن إسناده «غير مرتضى».", "mawaqif": [{"taliq": 6023, "mi": 0, "aya": 21, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "21/ 212", "qawl": "ابن عباس", "nass": "فعلى هذا القول تمام الوعيد فأولى، ثم يستأنف بعد، فيقال: {لهم طاعة وقول معروف} فتكون الطاعة مرفوعة بقوله: {لهم}", "qawaid": [], "tabi": ""}]}, {"id": 6024, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 652) قول قتادة، ثم علّق عليه قائلًا: «فـ {طاعة} على هذا القول: ابتداء، وخبره: لهم. والمعنى: أن ذلك منهم على جهة الخديعة، فإذا عزم الأمر ناقضوا وتعاصوا».", "mawaqif": [{"taliq": 6024, "mi": 0, "aya": 21, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 652", "qawl": "قتادة", "nass": "ف {طاعة} على هذا القول: ابتداء، وخبره: لهم. والمعنى: أن ذلك منهم على جهة الخديعة، فإذا عزم الأمر ناقضوا وتعاصوا", "qawaid": [], "tabi": ""}]}], "22": [{"id": 6026, "kinds": "توجيه،تعليق،نقل", "text": "وجّه ابنُ عطية (7/ 653) هذه القراءة، فقال: «قرأ علي بن أبي طالب: «إن تُوُلِّيتُمْ» بضم التاء والواو وكسر اللام المشددة على معنى: إن وليتكم ولاية الجَوْر فمِلتم إلى دنياهم دون إمام العدل. أو على معنى: إن توليتم بالتعذيب والتنكيل وأفعال العرب في جاهليتها وسيرتها من الغارات والسباء، فإنما كانت ثمرتها الإفساد في الأرض وقطيعة الرحم. وقيل معناها: إنْ تولاكم الناس ووكلكم الله إليهم».\nوذكر ابنُ عطية أن جمهور القراء قرؤوا ذلك: {إن تَولَيتم}، ثم علّق عليها، فقال: «والمعنى: إن أعرضتم عن الإسلام. وقال كعب الأحبار ومحمد بن كعب القرظي: المعنى: إن توليتم أمور الناس من الولاية. وعلى هذا قيل: إنها نزلت في بني هاشم وبني أمية. ذكره الثعلبي».", "mawaqif": [{"taliq": 6026, "mi": 0, "aya": 22, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "7/ 653", "qawl": "", "nass": "قرأ علي بن أبي طالب: «إن توليتم", "qawaid": [], "tabi": ""}, {"taliq": 6026, "mi": 0, "aya": 22, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "", "nass": "والمعنى: إن أعرضتم عن الإسلام. وقال كعب الأحبار ومحمد بن كعب القرظي: المعنى: إن توليتم أمور الناس من الولاية. وعلى هذا قيل: إنها نزلت في بني هاشم وبني أمية. ذكره الثعلبي", "qawaid": [], "tabi": ""}]}], "24": [{"id": 6027, "kinds": "توجيه،بيان،نقل", "text": "ذكر ابنُ القيم (2/ 454) قول مقاتل أنه فسر قوله: {أم على قلوب أقفالها} بالطبع. ثم وجّهه بقوله: «وكأنّ القلب بمنزلة الباب المرتج الذي قد ضُرب عليه قفل، فإنه ما لم يُفتح القفل لا يمكن فتح الباب والوصول إلى ما وراءه، وكذلك ما لم يُرفع الختم والقفل عن القلب لم يدخل الإيمان والقرآن».", "mawaqif": [{"taliq": 6027, "mi": 0, "aya": 24, "alam": "ابن القيم", "fil": "ذكر", "kind": "نقل", "ref": "2/ 454", "qawl": "مقاتل أنه", "nass": "وكأن القلب بمنزلة الباب المرتج الذي قد ضرب عليه قفل، فإنه ما لم يفتح القفل لا يمكن فتح الباب والوصول إلى ما وراءه، وكذلك ما لم يرفع الختم والقفل عن القلب لم يدخل الإيمان والقرآن", "qawaid": [], "tabi": ""}]}], "25": [{"id": 6028, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 654) قول من قال: إن هذه الآية نزلت في جماعة من اليهود. وقول من قال: نزلت في جماعة من المنافقين. ثم علّق بقوله: «والآية تعم كل مَن دخل في ضمن لفظها غابر الدهر».", "mawaqif": [{"taliq": 6028, "mi": 0, "aya": 25, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 654", "qawl": "", "nass": "والآية تعم كل من دخل في ضمن لفظها غابر الدهر", "qawaid": [], "tabi": ""}]}, {"id": 6029, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (21/ 218) غير قول قتادة.", "mawaqif": []}], "27": [{"id": 6031, "kinds": "بيان،نقل", "text": "ذكر ابنُ عطية (7/ 655) في الآية احتمالين، فقال: «وقوله تعالى: {فكيف إذا توفتهم} الآية، يحتمل أن يُتوعّدوا به على معنيين: أحدهما: هذا هلعهم وجزعهم لفرض القتال وقراع الأعداء، فكيف فزعهم وجزعهم إذا توفتهم الملائكة؟! والثاني أن يريد: هذه معاصيهم وعنادهم وكفرهم، فكيف تكون حالهم مع الله إذا توفتهم الملائكة؟! وقال الطبري: المعنى: والله يعلم إسرارهم فكيف علمه بها إذا توفتهم الملائكة».\nوبيّن ابنُ عطية أنّ الضمير في قوله: {يضربون} عائد على الملائكة، ثم ذكر قولًا آخر أنّه عائد على الكفار، وانتقده، فقال: «ومن قال: إن الضمير في: {يضربون} للكفار الذين يُتوفّون، فذلك ضعيف».", "mawaqif": [{"taliq": 6031, "mi": 0, "aya": 27, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 655", "qawl": "", "nass": "وقوله تعالى: {فكيف إذا توفتهم} الآية، يحتمل أن يتوعدوا به على معنيين: أحدهما: هذا هلعهم وجزعهم لفرض القتال وقراع الأعداء، فكيف فزعهم وجزعهم إذا توفتهم الملائكة؟! والثاني أن يريد: هذه معاصيهم وعنادهم وكفرهم، فكيف تكون حالهم مع الله إذا توفتهم الملائكة؟! وقال الطبري: المعنى: والله يعلم إسرارهم فكيف علمه بها إذا توفتهم الملائكة", "qawaid": [], "tabi": ""}, {"taliq": 6031, "mi": 0, "aya": 27, "alam": "ابن عطية", "fil": "بين", "kind": "بيان", "ref": "", "qawl": "", "nass": "ومن قال: إن الضمير في: {يضربون} للكفار الذين يتوفون، فذلك ضعيف", "qawaid": [], "tabi": ""}]}], "29": [{"id": 6032, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 656) قول ابن عباس، وعلّق عليه بقوله: «وهذا في الحقيقة ليس بتعريف تام، بل هو لفظ يشير إليهم على الإجمال، لا أنه سمّى أحدًا».", "mawaqif": [{"taliq": 6032, "mi": 0, "aya": 29, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 656", "qawl": "ابن عباس", "nass": "وهذا في الحقيقة ليس بتعريف تام، بل هو لفظ يشير إليهم على الإجمال، لا أنه سمى أحدا", "qawaid": [], "tabi": ""}]}], "31": [{"id": 6033, "kinds": "ترجيح،توجيه،بيان،نقل", "text": "ذكر ابنُ جرير (21/ 224) هذه القراءة، وبيّن أن لها وجهًا صحيحًا، ثم رجّح قراءة مَن قرأ ذلك بالنون لإجماع الحجة من القراء عليها، فقال: «والنون هي القراءة عندنا؛ لإجماع الحجة مِن القراء عليها، وإن كان للأخرى وجه صحيح».", "mawaqif": [{"taliq": 6033, "mi": 0, "aya": 31, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "21/ 224", "qawl": "", "nass": "والنون هي القراءة عندنا؛ لإجماع الحجة من القراء عليها، وإن كان للأخرى وجه صحيح", "qawaid": [], "tabi": ""}]}], "33": [{"id": 6035, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 659) ما جاء في قول مقاتل، ثم علّق عليه، فقال: «فإن كان هذا فالإبطال الذي نهوا عنه ليس بمعنى الإفساد التام؛ لأن الإفساد التام لا يكون إلا بالكفر، وإلا فالحسنات لا تبطلها المعاصي، وإن كانت الآية عامة على ظاهرها نهي الناس عن إبطال أعمالهم بالكفر، فالإبطال هو الإفساد التام».", "mawaqif": [{"taliq": 6035, "mi": 0, "aya": 33, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 659", "qawl": "مقاتل", "nass": "فإن كان هذا فالإبطال الذي نهوا عنه ليس بمعنى الإفساد التام؛ لأن الإفساد التام لا يكون إلا بالكفر، وإلا فالحسنات لا تبطلها المعاصي، وإن كانت الآية عامة على ظاهرها نهي الناس عن إبطال أعمالهم بالكفر، فالإبطال هو الإفساد التام", "qawaid": [], "tabi": ""}]}, {"id": 6036, "kinds": "حصر", "text": "لم يذكر ابن جرير (21/ 226) غير قول قتادة.", "mawaqif": []}], "34": [{"id": 6037, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 660) ما جاء في قول مقاتل، ثم علّق بقوله: «وظاهر الآية العموم في كل ما تناولته الصفة».", "mawaqif": [{"taliq": 6037, "mi": 0, "aya": 34, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 660", "qawl": "مقاتل", "nass": "وظاهر الآية العموم في كل ما تناولته الصفة", "qawaid": [], "tabi": ""}]}], "35": [{"id": 6038, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 660) هذه القراءة، ووجّهها، فقال: «وقرأ حمزة وأبو بكر عن عاصم: «إلى السِّلْمِ» بكسر السين، وهي قراءة الحسن، وأبي رجاء، والأعمش، وعيسى، وطلحة وهو بمعنى: المسالمة. وقال الحسن بن أبي الحسن وفرقة ممن كسر السين إنه بمعنى: إلى الإسلام، أي: لا تهنوا وتكونوا داعين إلى الإسلام فقط دون مقاتلين بسببه».", "mawaqif": [{"taliq": 6038, "mi": 0, "aya": 35, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 660", "qawl": "", "nass": "وقرأ حمزة وأبو بكر عن عاصم: «إلى السلم", "qawaid": [], "tabi": ""}]}, {"id": 6039, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 660) قول قتادة، ثم علّق قائلًا: «وهذا حسن ملتئم مع قوله: {وإن جنحوا للسلم فاجنح لها} [الأنفال: 61]».", "mawaqif": [{"taliq": 6039, "mi": 0, "aya": 35, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 660", "qawl": "قتادة", "nass": "وهذا حسن ملتئم مع قوله: {وإن جنحوا للسلم فاجنح لها} [الأنفال: 61]", "qawaid": [], "tabi": ""}]}, {"id": 6040, "kinds": "خلاف،توجيه،نقل", "text": "في موقع {وأنتم الأعلون} مِن الإعراب قولان، ذكرهما ابنُ عطية (7/ 660)، ووجّه معنى الآية عليهما، فقال: «وقوله: {وأنتم الأعلون} يحتمل موضعين: أحدهما: أن يكون في موضع الحال، المعنى: لا تهِنوا وأنتم في هذه الحال. والمعنى الثاني: أن يكون إخبارًا بنصره ومعونته».", "mawaqif": [{"taliq": 6040, "mi": 0, "aya": 35, "alam": "ابن عطية", "fil": "ذكرهما", "kind": "نقل", "ref": "7/ 660", "qawl": "", "nass": "وقوله: {وأنتم الأعلون} يحتمل موضعين: أحدهما: أن يكون في موضع الحال، المعنى: لا تهنوا وأنتم في هذه الحال. والمعنى الثاني: أن يكون إخبارا بنصره ومعونته", "qawaid": [], "tabi": ""}]}, {"id": 6042, "kinds": "ترجيح،بيان،تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 660 - 661) ما أفاده قول مجاهد من أن «يَتِرَ» معناه: يُنقص ويذهب. ثم علَّق بقوله: «ومنه قوله عليه السلام: «من ترك صلاة العصر فكأنما وُتر أهله وماله». أي: ذُهب بجميع ذلك على جهة التغلّب والقهر، والمعنى: لن يتركم ثواب أعمالكم وجزاء أعمالكم، واللفظة مأخوذة من الوِتْر الذي هو الذّحْل [أي: الثأر]». ونقل أنّ فرقة ذهبت إلى أنه مأخوذ من الوِتْر الذي هو الفرْد، وأن المعنى: لن يفردكم من ثواب أعمالكم، ثم رجَّح أنها من النقص، فقال: «والأول أصح». ولم يذكر مستندًا.", "mawaqif": [{"taliq": 6042, "mi": 0, "aya": 35, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 660 - 661", "qawl": "مجاهد من", "nass": "يتر", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}], "37": [{"id": 6043, "kinds": "تعليق،نقل", "text": "ذكر ابنُ كثير (13/ 83) قول قتادة، ثم علّق قائلًا: «وصدق قتادة؛ فإنّ المال محبوب، ولا يُصرف إلا فيما هو أحبّ إلى الشخص منه».", "mawaqif": [{"taliq": 6043, "mi": 0, "aya": 37, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "13/ 83", "qawl": "قتادة", "nass": "وصدق قتادة؛ فإن المال محبوب، ولا يصرف إلا فيما هو أحب إلى الشخص منه", "qawaid": [], "tabi": ""}]}], "38": [{"id": 6045, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 662) في قوله: {عن نفسه} احتمالين، فقال: «وقوله: {عن نفسه} يحتمل معنيين: أحدهما: فإنما يبخل عن شُحّ نفسه. والآخر أن يكون بمنزلة: على؛ لأنك تقول: بخلت عليك وبخلت عنك، بمعنى: أمسكت عنك».", "mawaqif": [{"taliq": 6045, "mi": 0, "aya": 38, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 662", "qawl": "", "nass": "وقوله: {عن نفسه} يحتمل معنيين: أحدهما: فإنما يبخل عن شح نفسه. والآخر أن يكون بمنزلة: على؛ لأنك تقول: بخلت عليك وبخلت عنك، بمعنى: أمسكت عنك", "qawaid": [], "tabi": ""}]}, {"id": 6046, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 663) هذه الأقوال، ثم ذكر أن الثعلبي حكى أنّ القوم الغير: هم الملائكة.", "mawaqif": [{"taliq": 6046, "mi": 0, "aya": 38, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 663", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}]}, "athar": {"70784": {"num": 70784, "aya": 4, "qail": "عبد الملك ابن جريج", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الملك ابن جُرَيْج، في قوله: {ذَلِكَ ولَوْ يَشاءُ اللَّهُ لانْتَصَرَ مِنهُمْ}، قال: لأرسل عليهم مَلَكًا، فدمّر عليهم."}, "70786": {"num": 70786, "aya": 4, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {والَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ فَلَنْ يُضِلَّ أعْمالَهُمْ} الآية، قال: ذُكِر لنا: أنّ هذه الآية نزلتْ في يوم أُحد، ورسول الله صلى الله عليه وسلم في الشِّعب، وقد فشت فيهم الجراحات والقتْل، وقد نادى المشركون يومئذ: اعلُ هُبل. ونادى المسلمون: الله أعلى وأجلّ. فنادى المشركون: يوم بيوم بدر وإنّ الحرب سِجال، لنا عُزّى ولا عُزّى لكم. فقال رسول الله صلى الله عليه وسلم: «قولوا: الله مولانا ولا مولى لكم، إنّ القتلى مختلفة، أما قتْلانا فأحياء يُرزقون، وأما قتْلاكم ففي النار يُعذّبون»."}, "70787": {"num": 70787, "aya": 4, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن قتادة بن دعامة -من طريق معمر- {والَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ فَلَنْ يُضِلَّ أعْمالَهُمْ}، قال: الذين قُتلوا يوم أُحد."}, "70789": {"num": 70789, "aya": 4, "qail": "عبد الملك ابن جريج", "tabaqa": "تابع التابعين", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الملك ابن جُرَيْج، في قوله: {والَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ فَلَنْ يُضِلَّ أعْمالَهُمْ}، قال: نزلت فيمن قُتِل مِن أصحاب النبيِّ صلى الله عليه وسلم يوم أُحد."}, "70943": {"num": 70943, "aya": 25, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس -من طريق عطية العَوفيّ- {إنَّ الَّذِينَ ارْتَدُّوا عَلى أدْبارِهِمْ} إلى: {إسْرارَهُمْ}: هم أهل النِّفاق."}, "71038": {"num": 71038, "aya": 38, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {وإنْ تَتَوَلَّوْا يَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ}: العجَم؛ مِن عجَم الفرس."}, "70713": {"num": 70713, "aya": 1, "qail": "مقاتل بن سليمان", "tabaqa": "تابع التابعين", "bab": "نزول الآية", "text": "قال مقاتل بن سليمان: نزلت في اثني عشر رجلًا من قريش، وهم المُطْعِمُونَ مِن كفار مكة في مسيرهم إلى قتال النبي صلى الله عليه وسلم ببدر، منهم أبو جهل والحارث ابنا هشام، وشيبة وعُتبة ابنا ربيعة، وأُميّة وأُبيّ ابنا خلف، ومُنَبِّه ونبيه ابنا الحجاج، وأبو البَختريّ بن هشام، وربيعة بن الأسود، وحكيم بن حزام، والحارث بن عامر بن نوفل."}, "70716": {"num": 70716, "aya": 1, "qail": "مقاتل بن سليمان", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "قال مقاتل بن سليمان: {الَّذِينَ كَفَرُوا} بتوحيد الله، يعني: كفار مكة {وصَدُّوا} الناس {عَنْ سَبِيلِ اللَّهِ} يقول: منعوا الناس عن دين الله الإسلام {أضَلَّ أعْمالَهُمْ} يقول: أبطل اللهُ أعمالَهم، يعني: نفقتهم في غزاة بدر ومسيرهم ومكْرهم، أبطل الله ذلك كلّه في الآخرة، أبطل أعمالهم التي عملوا في الدنيا؛ لأنها كانت في غير إيمان."}, "70730": {"num": 70730, "aya": 4, "qail": "عبد الملك ابن جريج", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الملك ابن جُرَيْج، في قوله: {فَإذا لَقِيتُمُ الَّذِينَ كَفَرُوا فَضَرْبَ الرِّقابِ}، قال: مشركي العرب. يقول: فضَرْب الرّقاب حتى يقولوا: لا إله إلا الله."}, "70732": {"num": 70732, "aya": 4, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "قال عبد الله بن عباس: لَمّا كثر المسلمون واشتد سلطانهم أنزل الله عز وجل في الأسارى: {فَإمّا مَنًّا بَعْدُ وإمّا فِداءً}."}, "70733": {"num": 70733, "aya": 4, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق علي- في قوله {فَإمّا مَنًّا بَعْدُ وإمّا فِداءً}، قال: فجعل الله النبيَّ صلى الله عليه وسلم والمؤمنين بالخيار في الأسرى؛ إن شاءوا قتلوهم، وإن شاءوا استعبدوهم، وإن شاءوا فادَوهم."}, "70734": {"num": 70734, "aya": 4, "qail": "الحسن", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن، قال: أُتي الحَجّاج بأسارى، فدفع إلى ابن عمر رجلًا يقتله، فقال ابن عمر: ليس بهذا أُمِرنا، إنما قال الله: {حَتّى إذا أثْخَنْتُمُوهُمْ فَشُدُّوا الوَثاقَ فَإمّا مَنًّا بَعْدُ وإمّا فِداءً}، قال: البكاء بين يديه. فقال الحسن: لو كان هذا وأصحابه لابتدروا إليهم."}, "70738": {"num": 70738, "aya": 4, "qail": "عطاء", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "وعطاء، عن قوله: {فَإمّا مَنًّا بَعْدُ وإمّا فِداءً}، قال: أحدهما يَمُنُّ عليه، أو يُفادى. وقال الآخر: يصنع كما صنع رسول الله صلى الله عليه وسلم؛ يمُنّ عليه أويفادى."}, "70739": {"num": 70739, "aya": 4, "qail": "عطاء بن أبي رباح", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن عطاء [بن أبي رباح]-من طريق ابن جريج- في قوله: {فإما منا بعد وإما فداء}، قال: هذا في الأسارى؛ إما المن، وإما الفداء. وكان يُنكِر القتل صبرًا."}, "70742": {"num": 70742, "aya": 4, "qail": "عبد الكريم الجزري", "tabaqa": "تابع التابعين", "bab": "النسخ في الآية", "text": "عن عبد الكريم الجزري، قال: كُتِب إلى أبي بكر? في أسير أُسر، فذُكر أنهم التمسوه بفداء كذا وكذا، فقال أبو بكر: اقتلوه، لَقَتْل رجل مِن المشركين أحبُّ إلَيَّ مِن كذا وكذا."}, "70743": {"num": 70743, "aya": 4, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "النسخ في الآية", "text": "عن عبد الله بن عباس -من طريق عطية العَوفيّ- في قوله: {فَإمّا مَنًّا بَعْدُ وإمّا فِداءً}، قال: هذا منسوخ، نَسَخَتْها: {فَإذا انْسَلَخَ الأَشْهُرُ الحُرُمُ فاقْتُلُوا المُشْرِكِينَ} [التوبة: 5]."}, "71000": {"num": 71000, "aya": 35, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق المعتمر، عن أبيه- {فَلا تَهِنُوا وتَدْعُوا إلى السَّلْمِ"}, "70999": {"num": 70999, "aya": 35, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {فَلا تَهِنُوا}، قال: لا تضعفوا."}, "71002": {"num": 71002, "aya": 35, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {فَلا تَهِنُوا} يقول: لا تهُنْ فتضعُف، فيرى أنّك تدعوه إلى السّلم وأنت فوقه، وأعزّ منه."}, "70747": {"num": 70747, "aya": 4, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "النسخ في الآية", "text": "والحسن البصري ="}, "70748": {"num": 70748, "aya": 4, "qail": "عطاء بن يسار", "tabaqa": "تابعي", "bab": "النسخ في الآية", "text": "وعطاء بن يَسار ="}, "71004": {"num": 71004, "aya": 35, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق هارون- {فلا تهنوا وتدعوا إلى السَّلم}: يعني: الصلح، السّلم لغة."}, "71006": {"num": 71006, "aya": 35, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {وأَنْتُمُ الأَعْلَوْنَ}، قال: الغالبون، مِثل يوم أُحد تكون عليهم الدائرة."}, "71007": {"num": 71007, "aya": 35, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- {فَلا تَهِنُوا وتَدْعُوا إلى السَّلْمِ وأَنْتُمُ الأَعْلَوْنَ}، يقول: لا تكونوا أوَّل الطائفتين ضَرَعت لصاحبتها، ودَعَتها إلى الموادعة، وأنتم أولى بالله منهم."}, "70753": {"num": 70753, "aya": 4, "qail": "عطاء بن أبي رباح", "tabaqa": "تابعي", "bab": "النسخ في الآية", "text": "عن عطاء بن أبي رباح -من طريق ابن جُرَيْج-: أنه كان يكره قتْل أهل الشرك صَبْرًا، ويتلو: {فَشُدُّوا الوَثاقَ فَإمّا مَنًّا بَعْدُ وإمّا فِداءً}. قال: ثم نَسَخَتْها: {فَخُذُوهُمْ واقْتُلُوهُمْ حَيْثُ وجَدْتُمُوهُمْ} [النساء: 89]، ونزلت -زعموا- في العرب خاصّة، وقتَل النبيُّ صلى الله عليه وسلم عُقبةَ بن أبي مُعَيْط يوم بدر صبْرًا."}, "70754": {"num": 70754, "aya": 4, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "النسخ في الآية", "text": "عن قتادة بن دعامة -من طريق معمر-: {فَإمّا مَنًّا بَعْدُ وإمّا فِداءً} نسخها قوله: {فَإمّا تَثْقَفَنَّهُمْ فِي الحَرْبِ فَشَرِّدْ بِهِمْ مَن خَلْفَهُمْ} [الأنفال: 57]."}, "70755": {"num": 70755, "aya": 4, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "النسخ في الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {فَإمّا مَنًّا بَعْدُ وإمّا فِداءً}، قال: كان المسلمون إذا لَقُوا المشركين قاتلوهم، فإذا أسَروا منهم أسيرًا فليس لهم إلا أن يُفادُوه أو يمُنّوا عليه، ثم نَسَخ ذلك بعد: {فَإمّا تَثْقَفَنَّهُمْ فِي الحَرْبِ فَشَرِّدْ بِهِمْ مَن خَلْفَهُمْ} [الأنفال: 57]."}, "70756": {"num": 70756, "aya": 4, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "النسخ في الآية", "text": "عن قتادة بن دعامة، في قوله: {فَإمّا مَنًّا بَعْدُ وإمّا فِداءً}، قال: فرَخَّص لهم أن يمُنّوا على مَن شاءُوا منهم، فنسخ الله ذلك بعد في براءة، فقال: {فاقْتُلُوا المُشْرِكِينَ حَيْثُ وجَدْتُمُوهُمْ} [التوبة: 5]."}, "70757": {"num": 70757, "aya": 4, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "النسخ في الآية", "text": "عن إسماعيل السُّدّيّ -من طريق سفيان الثوري- {فَإمّا مَنًّا بَعْدُ وإمّا فِداءً}، قال: نَسَخَها {فاقْتُلُوا المُشْرِكِينَ حَيْثُ وجَدْتُمُوهُمْ} [التوبة: 5]."}, "71010": {"num": 71010, "aya": 35, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {فَلا تَهِنُوا} يقول: لا تهُنْ فتضعُف، فيرى أنك تدعوه إلى السّلم وأنت فوقه، وأعزّ منه، {وأَنْتُمُ الأَعْلَوْنَ} أنتم أعزّ منهم."}, "70759": {"num": 70759, "aya": 4, "qail": "عبد الملك ابن جريج", "tabaqa": "تابع التابعين", "bab": "النسخ في الآية", "text": "عن عبد الملك ابن جُرَيْج -من طريق ابن المبارك- أنه كان يقول في قوله: {فَإمّا مَنًّا بَعْدُ وإمّا فِداءً}: نَسَخَها قوله: {فاقْتُلُوا المُشْرِكِينَ حَيْثُ وجَدْتُمُوهُمْ} [التوبة: 5]."}, "71015": {"num": 71015, "aya": 35, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- {ولَنْ يَتِرَكُمْ أعْمالَكُمْ}، يقول: لن يظلمكم أعمالكم."}, "71011": {"num": 71011, "aya": 35, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "النسخ في الآية", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {فَلا تَهِنُوا وتَدْعُوا إلى السَّلْمِ وأَنْتُمُ الأَعْلَوْنَ}، قال: هذا منسوخ. قال: نَسخه القتال والجهاد. يقول: لا تضعُف أنت وتدعوهم أنت إلى السّلم وأنت الأعلى. قال: وهذا حين كانت العهود والهُدنة فيما بينه وبين المشركين قبل أن يكون القتال، … ثم جاء القتال بعد، فنسخ هذا أجمع، فأمره بجهادهم والغِلظة عليهم."}, "71013": {"num": 71013, "aya": 35, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {ولَنْ يَتِرَكُمْ}، قال: لن يَنقُصكم."}, "71017": {"num": 71017, "aya": 35, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ولَنْ يَتِرَكُمْ أعْمالَكُمْ}، قال: لن يظلمكم أعمالكم، ذلك {يترِكم}."}, "70769": {"num": 70769, "aya": 4, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن الحسن البصري -من طريق معمر- قال: لا تُقتَل الأسارى إلا في الحرب؛ يُهيَّب بهم العدو."}, "71025": {"num": 71025, "aya": 38, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ها أنْتُمْ هَؤُلاءِ تُدْعَوْنَ لِتُنْفِقُوا فِي سَبِيلِ اللَّهِ فَمِنكُمْ مَن يَبْخَلُ ومَن يَبْخَلْ فَإنَّما يَبْخَلُ عَنْ نَفْسِهِ واللَّهُ الغَنِيُّ وأَنْتُمُ الفُقَراءُ}، قال: ليس بالله -تعالى ذِكره- إليكم حاجة، وأنتم أحوج إليه."}, "71026": {"num": 71026, "aya": 38, "qail": "أبي هريرة", "tabaqa": "صحابي", "bab": "", "text": "عن أبي هريرة، قال: تلا رسول الله صلى الله عليه وسلم هذه الآية: {وإنْ تَتَوَلَّوْا يَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ ثُمَّ لا يَكُونُوا أمْثالَكُمْ}، فقالوا: يا رسول الله، مَن هؤلاء الذين إن تولّينا استُبدِلوا بنا ثم لا يكونوا أمثالنا؟ فضرب رسول الله على مَنكِب سلمان، ثم قال: «هذا وقومه، والذي نفسي بيده، لو كان الإيمان منوطًا بالثّرَيّا لتناوله رجالٌ مِن فارس»."}, "71027": {"num": 71027, "aya": 38, "qail": "أبي هريرة", "tabaqa": "صحابي", "bab": "", "text": "عن أبي هريرة، قال: لما نزلتْ: {وإنْ تَتَوَلَّوْا يَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ ثُمَّ لا يَكُونُوا أمْثالَكُمْ} قالوا: مَن هؤلاء؟ وسلمان إلى جنب النبي صلى الله عليه وسلم، فقال: «هم الفرس، هذا وقومه»."}, "70773": {"num": 70773, "aya": 4, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري، {حَتّى تَضَعَ الحَرْبُ أوْزارَها}، قال: حتى يُعبد اللهُ، ولا يُشرك به."}, "70774": {"num": 70774, "aya": 4, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد، ومعمر- قوله: {حَتّى تَضَعَ الحَرْبُ أوْزارَها} حتى لا يكون شرك."}, "70775": {"num": 70775, "aya": 4, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- قوله: {حَتّى تَضَعَ الحَرْبُ أوْزارَها}، قال: الحرب: مَن كان يقاتلهم، سمّاهم: حربًا."}, "71035": {"num": 71035, "aya": 38, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {وإنْ تَتَوَلَّوْا يَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ}، يقول: إن تولّيتم عن كتابي وطاعتي أستبدل قومًا غيركم، قادِرٌ -واللهِ- ربُّنا على ذلك؛ على أن يُهلكهم، ويأتي من بعدهم مَن هو خير منهم."}, "70782": {"num": 70782, "aya": 4, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {ذَلِكَ ولَوْ يَشاءُ اللَّهُ لانْتَصَرَ مِنهُمْ}، قال: إي، واللهِ، بجنوده الكثيرة، كلُّ خلْقه له جندٌ، فلو سَلَّط أضعفَ خلْقه لكان له جندًا."}}, "n_athar": {"0": 11, "1": 5, "2": 9, "3": 2, "4": 62, "5": 1, "6": 9, "7": 4, "8": 7, "9": 2, "10": 5, "11": 4, "12": 2, "13": 4, "14": 4, "15": 19, "16": 10, "17": 5, "18": 20, "19": 19, "20": 7, "21": 6, "22": 14, "23": 3, "24": 8, "25": 12, "26": 3, "27": 4, "28": 2, "29": 5, "30": 9, "31": 7, "32": 2, "33": 8, "34": 2, "35": 21, "36": 2, "37": 4, "38": 15}, "muh": ["ابن جرير", "ابن عطية", "ابن كثير", "ابن تيمية", "ابن القيم"], "ords": ["الأول", "الثاني", "الثالث", "الرابع", "الخامس", "السادس", "السابع", "الثامن", "التاسع", "العاشر"], "index": "فهرس.html"});